      END_STATE();
    case 15:
      ACCEPT_TOKEN(anon_sym_lda);
      END_STATE();
    case 16:
      ACCEPT_TOKEN(anon_sym_rep);
      END_STATE();
    case 17:
      if (lookahead == 'u') ADVANCE(23);
      END_STATE();
    case 18:
      ACCEPT_TOKEN(anon_sym_rts);
      END_STATE();
    case 19:
      ACCEPT_TOKEN(anon_sym_sep);
